from collections import deque
n, m = map(int, input().split())
adj = [[] for _ in range(n + 1)]
ok = True
for _ in range(m):
    u, v = map(int, input().split())
    if u == v:
        ok = False
    adj[u].append(v)
    adj[v].append(u)
col = [-1] * (n + 1)
for s in range(1, n + 1):
    if not ok:
        break
    if col[s] != -1:
        continue
    col[s] = 0
    q = deque([s])
    while q and ok:
        x = q.popleft()
        for y in adj[x]:
            if col[y] == -1:
                col[y] = col[x] ^ 1
                q.append(y)
            elif col[y] == col[x]:
                ok = False
                break
print('YES' if ok else 'NO')

from collections import deque
r, c = map(int, input().split())
g = [list(map(int, input().split())) for _ in range(r)]
q = deque()
fresh = 0
for i in range(r):
    for j in range(c):
        if g[i][j] == 2:
            q.append((i, j, 0))
        elif g[i][j] == 1:
            fresh += 1
t = 0
while q:
    i, j, d = q.popleft()
    t = max(t, d)
    for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
        if 0 <= a < r and 0 <= b < c and g[a][b] == 1:
            g[a][b] = 2
            fresh -= 1
            q.append((a, b, d + 1))
print(t if fresh == 0 else -1)

from collections import deque
b, e = input().split()
n = int(input())
words = set(input().split())
if e not in words:
    print(0)
else:
    dist = {b: 1}
    q = deque([b])
    ans = 0
    letters = 'abcdefghijklmnopqrstuvwxyz'
    while q:
        w = q.popleft()
        if w == e:
            ans = dist[w]
            break
        for i in range(len(w)):
            for ch in letters:
                if ch != w[i]:
                    t = w[:i] + ch + w[i + 1:]
                    if t in words and t not in dist:
                        dist[t] = dist[w] + 1
                        q.append(t)
    print(ans)

r, c = map(int, input().split())
g = [input().strip() for _ in range(r)]
lab = [[0] * c for _ in range(r)]
size = [0]
for i in range(r):
    for j in range(c):
        if g[i][j] == '1' and lab[i][j] == 0:
            k = len(size)
            lab[i][j] = k
            st = [(i, j)]
            cnt = 0
            while st:
                x, y = st.pop()
                cnt += 1
                for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= a < r and 0 <= b < c and g[a][b] == '1' and lab[a][b] == 0:
                        lab[a][b] = k
                        st.append((a, b))
            size.append(cnt)
best = max(size)
for i in range(r):
    for j in range(c):
        if g[i][j] == '0':
            seen = set()
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < r and 0 <= b < c and lab[a][b]:
                    seen.add(lab[a][b])
            best = max(best, 1 + sum(size[k] for k in seen))
print(best)

