n, m = map(int, input().split())
adj = [[] for _ in range(n + 1)]
for i in range(m):
    u, v = map(int, input().split())
    adj[u].append((v, i))
    adj[v].append((u, i))
tin = [0] * (n + 1)
low = [0] * (n + 1)
timer = 1
res = []
for s in range(1, n + 1):
    if tin[s]:
        continue
    tin[s] = low[s] = timer
    timer += 1
    st = [(s, -1, 0)]
    while st:
        x, pe, it = st[-1]
        if it < len(adj[x]):
            st[-1] = (x, pe, it + 1)
            y, ei = adj[x][it]
            if ei == pe:
                continue
            if tin[y]:
                low[x] = min(low[x], tin[y])
            else:
                tin[y] = low[y] = timer
                timer += 1
                st.append((y, ei, 0))
        else:
            st.pop()
            if st:
                p = st[-1][0]
                low[p] = min(low[p], low[x])
                if low[x] > tin[p]:
                    res.append((min(p, x), max(p, x)))
res.sort()
print(len(res))
for u, v in res:
    print(u, v)
